/**
 * Reads website/js/locales/en.json and es.json and writes bundled-locales.js
 * for use when opening the site over file:// (fetch to JSON is blocked).
 * Run: node website/scripts/build-locales-bundle.js
 */
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..", "js", "locales");
const en = JSON.parse(fs.readFileSync(path.join(root, "en.json"), "utf8"));
const es = JSON.parse(fs.readFileSync(path.join(root, "es.json"), "utf8"));
const enStrings = en.strings || en;
const esStrings = es.strings || es;

const out = `/* Generated by website/scripts/build-locales-bundle.js — do not edit by hand; run the script after changing en.json or es.json */
(function (global) {
  "use strict";
  global.__FLC_LOCALES = {
    en: ${JSON.stringify(enStrings)},
    es: ${JSON.stringify(esStrings)}
  };
})(typeof window !== "undefined" ? window : this);
`;

const dest = path.join(root, "bundled-locales.js");
fs.writeFileSync(dest, out, "utf8");
console.log("Wrote", dest);
